const pptxgen = require("pptxgenjs");
const fs = require("fs");

// ============================================================
// DeepSeek-V2 Presentation
// ============================================================

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "DeepSeek-V2 Paper Review";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";
pres.subject = "DeepSeek-V2 Architecture and Performance";

// ============================================================
// Color Palette: Midnight Executive (navy dominant)
// Primary: 1E2761 (navy)
// Secondary: CADCFC (ice blue)
// Accent: FFFFFF (white)
// Plus supporting tones
// ============================================================
const C = {
  navy: "1E2761",
  iceBlue: "CADCFC",
  white: "FFFFFF",
  slate: "475569",
  lightGray: "F1F5F9",
  teal: "0D9488",
  coral: "F96167",
  gold: "F9E795",
  chartPrimary: "0D9488",
  chartSecondary: "14B8A6",
  chartTertiary: "5EEAD4",
  chartAccent: "F96167",
  chartNeutral: "94A3B8",
};

// ============================================================
// Typography helpers
// ============================================================
function titleOpts(extra = {}) {
  return { fontSize: 32, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle", ...extra };
}
function subtitleOpts(extra = {}) {
  return { fontSize: 18, bold: false, color: C.slate, fontFace: "Calibri", align: "left", valign: "middle", ...extra };
}
function bodyOpts(extra = {}) {
  return { fontSize: 14, color: C.slate, fontFace: "Calibri", align: "left", valign: "top", ...extra };
}
function statLabelOpts(extra = {}) {
  return { fontSize: 12, color: C.slate, fontFace: "Calibri", align: "center", valign: "top", ...extra };
}
function statNumOpts(extra = {}) {
  return { fontSize: 36, bold: true, color: C.teal, fontFace: "Calibri", align: "center", valign: "middle", ...extra };
}

// ============================================================
// Slide 1: Title
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Decorative accent bar top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

  // Title
  slide.addText("DeepSeek-V2: A Strong, Economical, and Efficient MoE Language Model", {
    x: 0.8, y: 1.6, w: 8.4, h: 1.4,
    fontSize: 38, bold: true, color: C.white, fontFace: "Calibri",
    align: "left", valign: "middle"
  });

  // Subtitle stats
  slide.addText([
    { text: "236B total parameters  ·  21B activated per token  ·  128K context length", options: { breakLine: true } },
    { text: "arXiv:2405.04434", options: { breakLine: true } },
  ], {
    x: 0.8, y: 3.2, w: 8.4, h: 1.0,
    fontSize: 16, color: C.iceBlue, fontFace: "Calibri",
    align: "left", valign: "top"
  });

  // Bottom accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// ============================================================
// Slide 2: Motivation & Challenge
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  // Title
  slide.addText("The LLM Scaling Dilemma: Performance vs. Cost & Speed", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Three pain points as cards
  const cardY = 1.2;
  const cardW = 2.8;
  const cardH = 3.2;
  const gap = 0.3;
  const startX = 0.5;

  const cards = [
    { title: "Training Cost", body: "Larger dense models demand massive compute budgets. Scaling beyond 60B+ parameters becomes prohibitively expensive for most organizations.", color: C.coral },
    { title: "KV Cache Bottleneck", body: "Standard Multi-Head Attention stores full key-value pairs per head per token, exploding memory usage during long-context generation.", color: C.gold },
    { title: "Inference Throughput", body: "Memory pressure and dense FFN computation limit serving capacity, making high-performance LLMs costly to deploy at scale.", color: C.teal },
  ];

  cards.forEach((c, i) => {
    const x = startX + i * (cardW + gap);
    // Card bg
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
    });
    // Accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: 0.08,
      fill: { color: c.color }, line: { color: c.color, width: 0 }
    });
    // Title
    slide.addText(c.title, {
      x: x + 0.15, y: cardY + 0.25, w: cardW - 0.3, h: 0.4,
      fontSize: 16, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
    });
    // Body
    slide.addText(c.body, {
      x: x + 0.15, y: cardY + 0.75, w: cardW - 0.3, h: 2.2,
      fontSize: 13, color: C.slate, fontFace: "Calibri", align: "left", valign: "top"
    });
  });

  // Bottom insight banner
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.7, w: 9, h: 0.7,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  slide.addText("Solution: Combine sparse MoE routing with compressed attention to break the cost–performance trade-off.", {
    x: 0.7, y: 4.7, w: 8.6, h: 0.7,
    fontSize: 14, bold: true, color: C.white, fontFace: "Calibri", align: "left", valign: "middle"
  });
}

// ============================================================
// Slide 3: Architecture Overview
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("DeepSeek-V2 Architecture: MLA + DeepSeekMoE", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Left: diagram image
  slide.addImage({
    path: "/app/benchmark/assets/figure_1.jpg",
    x: 0.5, y: 1.1, w: 5.2, h: 3.8,
    sizing: { type: "contain", w: 5.2, h: 3.8 }
  });

  // Right: two stacked blocks
  const rightX = 6.0;
  const blockW = 3.5;
  const blockH = 1.7;
  const blockGap = 0.3;

  // MLA block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1, w: blockW, h: blockH,
    fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1, w: 0.08, h: blockH,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText("Multi-Head Latent Attention (MLA)", {
    x: rightX + 0.2, y: 1.15, w: blockW - 0.35, h: 0.4,
    fontSize: 15, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
  });
  slide.addText("Low-rank KV joint compression + decoupled RoPE. Caches a compact latent vector instead of full K/V per head.", {
    x: rightX + 0.2, y: 1.55, w: blockW - 0.35, h: 1.1,
    fontSize: 12, color: C.slate, fontFace: "Calibri", align: "left", valign: "top"
  });

  // DeepSeekMoE block
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1 + blockH + blockGap, w: blockW, h: blockH,
    fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: rightX, y: 1.1 + blockH + blockGap, w: 0.08, h: blockH,
    fill: { color: C.coral }, line: { color: C.coral, width: 0 }
  });
  slide.addText("DeepSeekMoE Feed-Forward", {
    x: rightX + 0.2, y: 1.15 + blockH + blockGap, w: blockW - 0.35, h: 0.4,
    fontSize: 15, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
  });
  slide.addText("Shared + routed experts with fine-grained segmentation, device-limited routing, and load-balancing losses.", {
    x: rightX + 0.2, y: 1.55 + blockH + blockGap, w: blockW - 0.35, h: 1.1,
    fontSize: 12, color: C.slate, fontFace: "Calibri", align: "left", valign: "top"
  });

  // Bottom stats
  slide.addText("236B total  ·  21B activated  ·  128K context", {
    x: rightX, y: 4.5, w: blockW, h: 0.4,
    fontSize: 13, bold: true, color: C.teal, fontFace: "Calibri", align: "left", valign: "middle"
  });
}

// ============================================================
// Slide 4: MLA Mechanism
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("Multi-Head Latent Attention Compresses KV Cache by 93.3%", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Left: attention comparison image
  slide.addImage({
    path: "/app/benchmark/assets/figure_2.jpg",
    x: 0.5, y: 1.1, w: 5.0, h: 3.6,
    sizing: { type: "contain", w: 5.0, h: 3.6 }
  });

  // Right: bullet explanation
  const rightX = 5.8;
  slide.addText([
    { text: "Problem: MHA stores full K/V per head per token — cache grows linearly with layers, heads, and sequence length.", options: { bullet: true, breakLine: true } },
    { text: "GQA/MQA shrink cache but sacrifice expressiveness and accuracy.", options: { bullet: true, breakLine: true } },
    { text: "MLA innovation: compress keys and values into a single low-rank latent vector c_t^KV.", options: { bullet: true, breakLine: true } },
    { text: "During inference, reconstruct full K/V plus a decoupled RoPE positional key via learned projections.", options: { bullet: true, breakLine: true } },
    { text: "Result: better performance than MHA with 93.3% less KV cache.", options: { bullet: true } },
  ], {
    x: rightX, y: 1.2, w: 3.7, h: 3.4,
    fontSize: 13, color: C.slate, fontFace: "Calibri", align: "left", valign: "top",
    paraSpaceAfter: 8
  });

  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 9, h: 0.6,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  slide.addText("MLA is a strictly better alternative to GQA/MQA for inference efficiency.", {
    x: 0.7, y: 4.75, w: 8.6, h: 0.6,
    fontSize: 14, bold: true, color: C.white, fontFace: "Calibri", align: "left", valign: "middle"
  });
}

// ============================================================
// Slide 5: DeepSeekMoE
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Two-column layout
  const colW = 4.3;
  const colX1 = 0.5;
  const colX2 = 5.2;
  const colY = 1.1;
  const colH = 3.6;

  // Left column: shared vs routed
  slide.addShape(pres.shapes.RECTANGLE, {
    x: colX1, y: colY, w: colW, h: colH,
    fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: colX1, y: colY, w: colW, h: 0.08,
    fill: { color: C.coral }, line: { color: C.coral, width: 0 }
  });
  slide.addText("Expert Design", {
    x: colX1 + 0.15, y: colY + 0.15, w: colW - 0.3, h: 0.4,
    fontSize: 16, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
  });
  slide.addText([
    { text: "Shared experts (N_s): always active, capture common knowledge across all tokens.", options: { bullet: true, breakLine: true } },
    { text: "Routed experts (N_r): sparsely activated via top-K_r router per token.", options: { bullet: true, breakLine: true } },
    { text: "Fine-grained segmentation increases specialization potential without exploding parameter count.", options: { bullet: true } },
  ], {
    x: colX1 + 0.15, y: colY + 0.6, w: colW - 0.3, h: 2.8,
    fontSize: 13, color: C.slate, fontFace: "Calibri", align: "left", valign: "top",
    paraSpaceAfter: 8
  });

  // Right column: routing & training
  slide.addShape(pres.shapes.RECTANGLE, {
    x: colX2, y: colY, w: colW, h: colH,
    fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: colX2, y: colY, w: colW, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText("Routing & Training Optimizations", {
    x: colX2 + 0.15, y: colY + 0.15, w: colW - 0.3, h: 0.4,
    fontSize: 16, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
  });
  slide.addText([
    { text: "Device-limited routing: each token is routed to experts on at most M devices, cutting cross-node communication.", options: { bullet: true, breakLine: true } },
    { text: "Auxiliary losses enforce load balance across experts and devices.", options: { bullet: true, breakLine: true } },
    { text: "Token-dropping during training prevents expert overflow without affecting inference.", options: { bullet: true } },
  ], {
    x: colX2 + 0.15, y: colY + 0.6, w: colW - 0.3, h: 2.8,
    fontSize: 13, color: C.slate, fontFace: "Calibri", align: "left", valign: "top",
    paraSpaceAfter: 8
  });
}

// ============================================================
// Slide 6: Efficiency Gains (side-by-side comparison)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("42.5% Training Cost Reduction and 5.76× Generation Throughput vs. DeepSeek 67B", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Three large stat cards across the slide
  const cardW = 2.8;
  const cardH = 2.6;
  const gap = 0.3;
  const startX = 0.5;
  const cardY = 1.2;

  const stats = [
    { num: "42.5%", label: "Training Cost Reduction", desc: "DeepSeek-V2 trains cheaper than the 67B dense predecessor despite 236B total params.", color: C.teal },
    { num: "93.3%", label: "KV Cache Reduction", desc: "MLA compresses the cache to a latent vector, slashing memory pressure during generation.", color: C.coral },
    { num: "5.76×", label: "Generation Throughput", desc: "Higher maximum throughput enabled by smaller cache and sparse activation.", color: C.gold },
  ];

  stats.forEach((s, i) => {
    const x = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: 0.08,
      fill: { color: s.color }, line: { color: s.color, width: 0 }
    });
    slide.addText(s.num, {
      x, y: cardY + 0.25, w: cardW, h: 0.7,
      fontSize: 40, bold: true, color: s.color, fontFace: "Calibri", align: "center", valign: "middle"
    });
    slide.addText(s.label, {
      x, y: cardY + 0.95, w: cardW, h: 0.35,
      fontSize: 14, bold: true, color: C.navy, fontFace: "Calibri", align: "center", valign: "middle"
    });
    slide.addText(s.desc, {
      x: x + 0.15, y: cardY + 1.35, w: cardW - 0.3, h: 1.1,
      fontSize: 12, color: C.slate, fontFace: "Calibri", align: "center", valign: "top"
    });
  });

  // Bottom comparison table
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.1, w: 9, h: 1.3,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  slide.addText([
    { text: "DeepSeek 67B (dense)", options: { bold: true, color: C.iceBlue, breakLine: true } },
    { text: "67B activated  ·  Standard MHA  ·  Dense FFN  ·  Baseline throughput", options: { color: C.white } },
  ], {
    x: 0.7, y: 4.15, w: 4.0, h: 1.1,
    fontSize: 12, fontFace: "Calibri", align: "left", valign: "top"
  });
  slide.addText([
    { text: "DeepSeek-V2 (MoE + MLA)", options: { bold: true, color: C.iceBlue, breakLine: true } },
    { text: "21B activated  ·  MLA (93.3% less cache)  ·  Sparse MoE FFN  ·  5.76× throughput", options: { color: C.white } },
  ], {
    x: 5.0, y: 4.15, w: 4.4, h: 1.1,
    fontSize: 12, fontFace: "Calibri", align: "left", valign: "top"
  });
}

// ============================================================
// Slide 7: MMLU Performance Comparison (scatter chart)
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("DeepSeek-V2 Tops MMLU Among Open-Source Models at Only 21B Activated Parameters", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Scatter chart: MMLU vs Activated Params
  // We use a bubble chart with uniform bubble size to simulate scatter
  const chartData = [
    {
      name: "DeepSeek-V2",
      labels: ["DeepSeek-V2"],
      values: [{ x: 21, y: 78.5, size: 15 }]
    },
    {
      name: "LLaMA 3 70B",
      labels: ["LLaMA 3 70B"],
      values: [{ x: 70, y: 77.0, size: 12 }]
    },
    {
      name: "Mixtral 8×22B",
      labels: ["Mixtral 8×22B"],
      values: [{ x: 39, y: 77.6, size: 12 }]
    },
    {
      name: "Qwen1.5 72B",
      labels: ["Qwen1.5 72B"],
      values: [{ x: 72, y: 75.6, size: 12 }]
    },
    {
      name: "DeepSeek 67B",
      labels: ["DeepSeek 67B"],
      values: [{ x: 67, y: 73.0, size: 10 }]
    },
    {
      name: "LLaMA 2 70B",
      labels: ["LLaMA 2 70B"],
      values: [{ x: 70, y: 69.0, size: 10 }]
    },
    {
      name: "Mixtral 8×7B",
      labels: ["Mixtral 8×7B"],
      values: [{ x: 13, y: 70.6, size: 10 }]
    },
    {
      name: "LLaMA 3 8B",
      labels: ["LLaMA 3 8B"],
      values: [{ x: 8, y: 65.0, size: 8 }]
    },
  ];

  slide.addChart(pres.charts.BUBBLE, chartData, {
    x: 0.5, y: 1.0, w: 6.0, h: 4.2,
    showTitle: false,
    chartColors: [C.teal, C.chartNeutral, C.chartNeutral, C.chartNeutral, C.chartNeutral, C.chartNeutral, C.chartNeutral, C.chartNeutral],
    chartArea: { fill: { color: C.white }, roundedCorners: true },
    catAxisTitle: "Activated Parameters (B)",
    catAxisTitleColor: C.navy,
    catAxisTitleFontSize: 12,
    catAxisLabelColor: C.slate,
    catAxisLabelFontSize: 10,
    valAxisTitle: "MMLU Score",
    valAxisTitleColor: C.navy,
    valAxisTitleFontSize: 12,
    valAxisLabelColor: C.slate,
    valAxisLabelFontSize: 10,
    valGridLine: { color: "E2E8F0", size: 0.5 },
    catGridLine: { style: "none" },
    showLegend: true,
    legendPos: "r",
    legendFontSize: 9,
    legendColor: C.slate,
    lineDataSymbol: "circle",
    lineDataSymbolSize: 10,
    showValue: false,
  });

  // Right-side insight box
  const insightX = 6.8;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: insightX, y: 1.0, w: 2.7, h: 4.2,
    fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: insightX, y: 1.0, w: 0.08, h: 4.2,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText("Pareto-Optimal Position", {
    x: insightX + 0.15, y: 1.1, w: 2.4, h: 0.4,
    fontSize: 15, bold: true, color: C.navy, fontFace: "Calibri", align: "left", valign: "middle"
  });
  slide.addText([
    { text: "Highest MMLU score (78.5) among all listed open-source models.", options: { bullet: true, breakLine: true } },
    { text: "Activates only 21B parameters — 3.3× fewer than LLaMA 3 70B and 1.9× fewer than Mixtral 8×22B.", options: { bullet: true, breakLine: true } },
    { text: "Strictly dominates dense 70B-class competitors on the cost–accuracy frontier.", options: { bullet: true } },
  ], {
    x: insightX + 0.15, y: 1.55, w: 2.4, h: 3.4,
    fontSize: 12, color: C.slate, fontFace: "Calibri", align: "left", valign: "top",
    paraSpaceAfter: 8
  });
}

// ============================================================
// Slide 8: Alignment Results
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };

  slide.addText("DeepSeek-V2 Chat (RL) Rivals Closed-Source Models on Chinese Benchmarks", {
    x: 0.5, y: 0.35, w: 9, h: 0.6,
    ...titleOpts()
  });

  // Pipeline description
  slide.addText("Alignment Pipeline: SFT on 1.5M conversational sessions → GRPO-based reinforcement learning", {
    x: 0.5, y: 1.0, w: 9, h: 0.35,
    fontSize: 14, bold: true, color: C.teal, fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Three benchmark stat cards
  const cardW = 2.8;
  const cardH = 2.2;
  const gap = 0.3;
  const startX = 0.5;
  const cardY = 1.5;

  const benchmarks = [
    { num: "38.9%", label: "AlpacaEval 2.0", sub: "Length-controlled win rate", color: C.teal },
    { num: "8.97", label: "MT-Bench", sub: "Overall score", color: C.coral },
    { num: "7.91", label: "AlignBench", sub: "Overall (Chinese)", color: C.gold },
  ];

  benchmarks.forEach((b, i) => {
    const x = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: cardH,
      fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y: cardY, w: cardW, h: 0.08,
      fill: { color: b.color }, line: { color: b.color, width: 0 }
    });
    slide.addText(b.num, {
      x, y: cardY + 0.25, w: cardW, h: 0.7,
      fontSize: 38, bold: true, color: b.color, fontFace: "Calibri", align: "center", valign: "middle"
    });
    slide.addText(b.label, {
      x, y: cardY + 0.95, w: cardW, h: 0.3,
      fontSize: 14, bold: true, color: C.navy, fontFace: "Calibri", align: "center", valign: "middle"
    });
    slide.addText(b.sub, {
      x, y: cardY + 1.25, w: cardW, h: 0.3,
      fontSize: 11, color: C.slate, fontFace: "Calibri", align: "center", valign: "top"
    });
  });

  // Bottom callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.95, w: 9, h: 0.7,
    fill: { color: C.navy }, line: { color: C.navy, width: 0 }
  });
  slide.addText("On AlignBench (Chinese), DeepSeek-V2 Chat (RL) outperforms all open-source models and most closed-source models.", {
    x: 0.7, y: 3.95, w: 8.6, h: 0.7,
    fontSize: 14, bold: true, color: C.white, fontFace: "Calibri", align: "left", valign: "middle"
  });
}

// ============================================================
// Slide 9: Key Takeaways
// ============================================================
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };

  // Top accent
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });

  slide.addText("Key Takeaways: Architectural Innovation Unlocks Efficient Scaling", {
    x: 0.8, y: 0.5, w: 8.4, h: 0.7,
    fontSize: 32, bold: true, color: C.white, fontFace: "Calibri", align: "left", valign: "middle"
  });

  // Five takeaway blocks in a 2x3-ish grid (5 items)
  const items = [
    { title: "MLA > MHA, GQA, MQA", body: "Superior accuracy with 93.3% KV cache reduction via low-rank joint compression." },
    { title: "DeepSeekMoE Cuts Training Cost", body: "42.5% cheaper than a 67B dense model by sparsely activating 21B of 236B parameters." },
    { title: "Pareto-Optimal MMLU", body: "Highest open-source MMLU score (78.5) while activating far fewer parameters than 70B rivals." },
    { title: "5.76× Throughput Gain", body: "Smaller cache + sparse activation make large-scale deployment practical and economical." },
    { title: "Strong Multilingual Alignment", body: "Best open-source chat model in Chinese; competitive with closed-source systems in English." },
  ];

  const blockW = 4.3;
  const blockH = 1.35;
  const col1X = 0.5;
  const col2X = 5.2;
  const startY = 1.4;
  const vGap = 0.25;

  items.forEach((item, i) => {
    const col = i % 2;
    const row = Math.floor(i / 2);
    const x = col === 0 ? col1X : col2X;
    const y = startY + row * (blockH + vGap);

    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: blockW, h: blockH,
      fill: { color: "2A3A7A" }, line: { color: C.iceBlue, width: 1 }
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x, y, w: 0.08, h: blockH,
      fill: { color: C.teal }, line: { color: C.teal, width: 0 }
    });
    slide.addText(item.title, {
      x: x + 0.2, y: y + 0.1, w: blockW - 0.35, h: 0.35,
      fontSize: 14, bold: true, color: C.iceBlue, fontFace: "Calibri", align: "left", valign: "middle"
    });
    slide.addText(item.body, {
      x: x + 0.2, y: y + 0.45, w: blockW - 0.35, h: 0.8,
      fontSize: 12, color: C.white, fontFace: "Calibri", align: "left", valign: "top"
    });
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// ============================================================
// Write file
// ============================================================
pres.writeFile({ fileName: "/app/output/final_deck.pptx" })
  .then(() => console.log("Presentation saved to /app/output/final_deck.pptx"))
  .catch((err) => {
    console.error("Error saving presentation:", err);
    process.exit(1);
  });

