const pptxgen = require('pptxgenjs');
const fs = require('fs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.author = 'DeepSeek-V2 Paper Review';
pres.title = 'DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention';
pres.subject = 'DeepSeek-V2 Architecture and Performance';

const C = {
  navy: '1E2761',
  iceBlue: 'CADCFC',
  white: 'FFFFFF',
  slate: '475569',
  lightGray: 'F1F5F9',
  teal: '0D9488',
  coral: 'F96167',
  gold: 'F9E795',
  chartNeutral: '94A3B8',
};

function titleOpts(extra = {}) {
  return { fontSize: 32, bold: true, color: C.navy, fontFace: 'Calibri', align: 'left', valign: 'middle', ...extra };
}

// Slide 1: Title
{
  const slide = pres.addSlide();
  slide.background = { color: C.navy };
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
  slide.addText('DeepSeek-V2: A Strong, Economical, and Efficient MoE Language Model', {
    x: 0.8, y: 1.6, w: 8.4, h: 1.4,
    fontSize: 38, bold: true, color: C.white, fontFace: 'Calibri', align: 'left', valign: 'middle'
  });
  slide.addText([
    { text: '236B total parameters  ·  21B activated per token  ·  128K context length', options: { breakLine: true } },
    { text: 'arXiv:2405.04434', options: { breakLine: true } },
  ], {
    x: 0.8, y: 3.2, w: 8.4, h: 1.0,
    fontSize: 16, color: C.iceBlue, fontFace: 'Calibri', align: 'left', valign: 'top'
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.545, w: 10, h: 0.08,
    fill: { color: C.teal }, line: { color: C.teal, width: 0 }
  });
}

// Slide 2: Motivation
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };
  slide.addText('The LLM Scaling Dilemma: Performance vs. Cost & Speed', {
    x: 0.5, y: 0.35, w: 9, h: 0.6, ...titleOpts()
  });
  const cardY = 1.2, cardW = 2.8, cardH = 3.2, gap = 0.3, startX = 0.5;
  const cards = [
    { title: 'Training Cost', body: 'Larger dense models demand massive compute budgets. Scaling beyond 60B+ parameters becomes prohibitively expensive for most organizations.', color: C.coral },
    { title: 'KV Cache Bottleneck', body: 'Standard Multi-Head Attention stores full key-value pairs per head per token, exploding memory usage during long-context generation.', color: C.gold },
    { title: 'Inference Throughput', body: 'Memory pressure and dense FFN computation limit serving capacity, making high-performance LLMs costly to deploy at scale.', color: C.teal },
  ];
  cards.forEach((c, i) => {
    const x = startX + i * (cardW + gap);
    slide.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: cardH, fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 } });
    slide.addShape(pres.shapes.RECTANGLE, { x, y: cardY, w: cardW, h: 0.08, fill: { color: c.color }, line: { color: c.color, width: 0 } });
    slide.addText(c.title, { x: x + 0.15, y: cardY + 0.25, w: cardW - 0.3, h: 0.4, fontSize: 16, bold: true, color: C.navy, fontFace: 'Calibri', align: 'left', valign: 'middle' });
    slide.addText(c.body, { x: x + 0.15, y: cardY + 0.75, w: cardW - 0.3, h: 2.2, fontSize: 13, color: C.slate, fontFace: 'Calibri', align: 'left', valign: 'top' });
  });
  slide.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.7, w: 9, h: 0.7, fill: { color: C.navy }, line: { color: C.navy, width: 0 } });
  slide.addText('Solution: Combine sparse MoE routing with compressed attention to break the cost–performance trade-off.', {
    x: 0.7, y: 4.7, w: 8.6, h: 0.7, fontSize: 14, bold: true, color: C.white, fontFace: 'Calibri', align: 'left', valign: 'middle'
  });
}

// Slide 3: Architecture Overview
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };
  slide.addText('DeepSeek-V2 Architecture: MLA + DeepSeekMoE', { x: 0.5, y: 0.35, w: 9, h: 0.6, ...titleOpts() });
  slide.addImage({ path: '/app/benchmark/assets/figure_1.jpg', x: 0.5, y: 1.1, w: 5.2, h: 3.8, sizing: { type: 'contain', w: 5.2, h: 3.8 } });
  const rightX = 6.0, blockW = 3.5, blockH = 1.7, blockGap = 0.3;
  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 1.1, w: blockW, h: blockH, fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 } });
  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 1.1, w: 0.08, h: blockH, fill: { color: C.teal }, line: { color: C.teal, width: 0 } });
  slide.addText('Multi-Head Latent Attention (MLA)', { x: rightX + 0.2, y: 1.15, w: blockW - 0.35, h: 0.4, fontSize: 15, bold: true, color: C.navy, fontFace: 'Calibri', align: 'left', valign: 'middle' });
  slide.addText('Low-rank KV joint compression + decoupled RoPE. Caches a compact latent vector instead of full K/V per head.', { x: rightX + 0.2, y: 1.55, w: blockW - 0.35, h: 1.1, fontSize: 12, color: C.slate, fontFace: 'Calibri', align: 'left', valign: 'top' });
  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 1.1 + blockH + blockGap, w: blockW, h: blockH, fill: { color: C.lightGray }, line: { color: C.iceBlue, width: 1 } });
  slide.addShape(pres.shapes.RECTANGLE, { x: rightX, y: 1.1 + blockH + blockGap, w: 0.08, h: blockH, fill: { color: C.coral }, line: { color: C.coral, width: 0 } });
  slide.addText('DeepSeekMoE Feed-Forward', { x: rightX + 0.2, y: 1.15 + blockH + blockGap, w: blockW - 0.35, h: 0.4, fontSize: 15, bold: true, color: C.navy, fontFace: 'Calibri', align: 'left', valign: 'middle' });
  slide.addText('Shared + routed experts with fine-grained segmentation, device-limited routing, and load-balancing losses.', { x: rightX + 0.2, y: 1.55 + blockH + blockGap, w: blockW - 0.35, h: 1.1, fontSize: 12, color: C.slate, fontFace: 'Calibri', align: 'left', valign: 'top' });
  slide.addText('236B total  ·  21B activated  ·  128K context', { x: rightX, y: 4.5, w: blockW, h: 0.4, fontSize: 13, bold: true, color: C.teal, fontFace: 'Calibri', align: 'left', valign: 'middle' });
}

// Slide 4: MLA
{
  const slide = pres.addSlide();
  slide.background = { color: C.white };
  slide.addText('Multi-Head Latent Attention Compresses KV Cache by 93.3%', { x: 0.5, y: 0.35, w: 9, h: 0.6, ...titleOpts() });
  slide.addImage({ path: '/app/benchmark/assets/figure_2.jpg', x: 0.5, y: 1.1, w: 5.0, h: 3.6, sizing: { type: 'contain', w: 5.0, h: 3.6 } });
  const rightX = 5.8;
  slide.addText([
    { text: 'Problem: MHA stores full K/V per head per token — cache grows linearly with layers, heads, and sequence length.', options: { bullet: true, breakLine: true } },
    { text: 'GQA/MQA shrink cache but sacrifice expressiveness and accuracy.', options: { bullet: true, breakLine: true } },
    { text: 'MLA innovation: compress keys and values into a single low-rank latent vector c_t^KV.', options: { bullet: true, breakLine: true } },
    { text: 'During inference, reconstruct full K/V plus a decoupled RoPE positional key via learned projections.', options: { bullet: true, breakLine: true } },
    { text: 'Result: better performance than MHA with 93.3% less KV cache.', options: { bullet: true } },
